      packed.x.labels.forEach((label,i)=>{line(i*packed.cellWidth,0,0,packed.artworkHeight??packed.height);const e=document.createElement('span');e.className='arrange-label x';e.textContent=label;e.style.whiteSpace='normal';e.style.overflowWrap='anywhere';e.style.lineHeight='1.15';layer.append(e);this.axisLabels.push({node:e,axis:'x',coordinate:(i+.5)*packed.cellWidth,step:packed.cellWidth,index:i});});
      packed.y.labels.forEach((label,i)=>{line(0,i*packed.cellHeight,packed.artworkWidth??packed.width,0);const e=document.createElement('span');e.className='arrange-label y';e.textContent=label;e.style.whiteSpace='normal';e.style.overflowWrap='anywhere';e.style.lineHeight='1.15';layer.append(e);this.axisLabels.push({node:e,axis:'y',coordinate:(i+.5)*packed.cellHeight,step:packed.cellHeight,index:i});});
